<script setup lang="ts">import {computed} from 'vue';import * as api from '../api/runs';import {useResource} from '../hooks/useResource';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import PatternTable from '../components/PatternTable.vue';import MedoidPanel from '../components/MedoidPanel.vue';const {data,error}=useResource(api.list,[]);const run=computed(()=>data.value.find(r=>r.id==='run-baseline')||data.value.find(r=>r.status==='completed'));</script><template><PageTitle chapter="01" title="先留下顺序，再解释差异" description="栖山秋展 · 匿名观展路径复核。子序列支持按旅程计数，代表序列由加权编辑距离选出。"/><Notice :error="error"/><template v-if="run"><div class="folio-stats"><div><small>匿名观展路径</small><strong>{{run.result.journeys}}</strong></div><div><small>唯一顺序</small><strong>{{run.result.unique_paths}}</strong></div><div><small>频繁子序列</small><strong>{{run.result.total_patterns}}</strong></div><p>转化 {{run.result.group_sizes.converted}} 条 / 退出 {{run.result.group_sizes.exited}} 条<br/>连续重复{{run.result.collapse_repeats?'已折叠':'保留'}} · 最长模式{{run.result.study.max_length}}</p></div><div class="editorial-grid"><section class="paper"><p class="eyebrow">COMMON ORDER / TOP SEQUENCES</p><h2>先看经常一起出现的顺序</h2><PatternTable :result="run.result" :limit="6"/></section><aside class="representatives"><h2>三份代表路径</h2><MedoidPanel :result="run.result"/></aside></div><div class="method-note">转化组与退出组的支持差只描述样本关联，不作因果、通道归因或路径优化承诺。</div></template><EmptyState v-else text="先录入触点与匿名路径，再建立挖掘方案。"/></template>
